def write_live():
    payload = {"testResults": [results[i] for i in sorted(results)]}
    tmp = SHOTS / "live-results.json.tmp"
    tmp.write_text(json.dumps(payload, ensure_ascii=False, indent=1), encoding="utf-8")
    os.replace(str(tmp), str(SHOTS / "live-results.json"))


def shot(idx):
    try:
        capture_screenshot(str(SHOTS / ("step-%02d.png" % idx)), full=True)
    except Exception as exc:
        print("screenshot failed for step %d: %s" % (idx, exc))


def record(idx, status, comment, screenshot=True):
    if screenshot:
        shot(idx)
    results[idx] = {"step": STEPS[idx - 1], "status": status, "comment": comment}
    write_live()
    print("step %02d  %-7s %s" % (idx, status, comment[:120].encode("ascii", "replace").decode()))


# ---------------------------------------------------------------- primitives

def jesc(value):
    return json.dumps(value)


def url():
    try:
        info = page_info()
        if isinstance(info, dict) and info.get("url"):
            return info["url"]
    except Exception:
        pass
    try:
        return js("location.href") or ""
    except Exception:
        return ""


def go(path):
    goto_url(BASE + path)
    wait_for_load()
    wait(0.6)


def setval(selector, value):
    return js(
        "(function(s,v){var el=document.querySelector(s);if(!el)return null;"
        "var p=el.tagName==='TEXTAREA'?HTMLTextAreaElement.prototype:"
        "(el.tagName==='SELECT'?HTMLSelectElement.prototype:HTMLInputElement.prototype);"
        "Object.getOwnPropertyDescriptor(p,'value').set.call(el,v);"
        "el.dispatchEvent(new Event('input',{bubbles:true}));"
        "el.dispatchEvent(new Event('change',{bubbles:true}));return el.value})(%s,%s)"
        % (jesc(selector), jesc(value))
    )


def click(selector):
    return js(
        "(function(s){var e=document.querySelector(s);if(!e)return false;e.click();return true})(%s)"
        % jesc(selector)
    )


def click_text(text, tag="button"):
    """Click the first <tag> whose trimmed innerText contains `text`."""
    return js(
        "(function(t,x){var e=Array.from(document.querySelectorAll(t)).find("
        "function(n){return ((n.innerText||'').trim().indexOf(x)>=0)&&!n.disabled});"
        "if(!e)return false;e.scrollIntoView({block:'center'});e.click();return true})(%s,%s)"
        % (jesc(tag), jesc(text))
    )


def body_text():
    try:
        return js("document.body.innerText") or ""
    except Exception:
        return ""


def has_text(text):
    return text in body_text()


def wait_text(text, timeout=30.0):
    end = time.time() + timeout
    while time.time() < end:
        if has_text(text):
            return True
        wait(0.5)
    return False


def wait_gone(text, timeout=60.0):
    end = time.time() + timeout
    while time.time() < end:
        if not has_text(text):
            return True
        wait(0.5)
    return False


def wait_url(fragment, timeout=30.0):
    end = time.time() + timeout
    while time.time() < end:
        if fragment in url():
            return True
        wait(0.4)
    return False


def count(selector):
    try:
        return js("document.querySelectorAll(%s).length" % jesc(selector)) or 0
    except Exception:
        return 0


def texts(selector):
    try:
        raw = js(
            "JSON.stringify(Array.from(document.querySelectorAll(%s)).map("
            "function(e){return (e.innerText||'').trim()}))" % jesc(selector)
        )
        return json.loads(raw) if raw else []
    except Exception:
        return []


