# ------------------------------------------------------------- test fixtures

def tone_wav(seconds=3.0, rate=16000, freq=420.0):
    frames = int(seconds * rate)
    data = bytearray()
    for i in range(frames):
        data += struct.pack("<h", int(2500 * math.sin(2 * math.pi * freq * i / rate)))
    header = b"RIFF" + struct.pack("<I", 36 + len(data)) + b"WAVE"
    header += b"fmt " + struct.pack("<IHHIIHH", 16, 1, 1, rate, rate * 2, 2, 16)
    header += b"data" + struct.pack("<I", len(data))
    return bytes(header) + bytes(data)


def silent_mp3(frames=40):
    # Minimal MPEG-1 Layer III frames (44.1 kHz, 128 kbit/s, mono). Enough for
    # the .mp3 intake path; the harness only needs the file to be accepted.
    out = bytearray()
    for _ in range(frames):
        out += b"\xff\xfb\x90\x00" + b"\x00" * 413
    return bytes(out)


