def set_input_files(paths):
    doc = cdp("DOM.getDocument")["root"]["nodeId"]
    node = cdp("DOM.querySelector", nodeId=doc, selector="input[type=file]")["nodeId"]
    cdp("DOM.setFileInputFiles", nodeId=node, files=[str(p) for p in paths])


def drop_file(path, mime):
    payload = base64.b64encode(Path(path).read_bytes()).decode("ascii")
    js(
        "(function(name,b64,mime){var bin=atob(b64);var bytes=new Uint8Array(bin.length);"
        "for(var i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);"
        "var file=new File([bytes],name,{type:mime});var dt=new DataTransfer();dt.items.add(file);"
        "var zone=document.querySelector('input[type=file]').parentElement;"
        "zone.dispatchEvent(new DragEvent('dragover',{bubbles:true,dataTransfer:dt}));"
        "zone.dispatchEvent(new DragEvent('drop',{bubbles:true,dataTransfer:dt}));"
        "return true})(%s,%s,%s)" % (jesc(Path(path).name), jesc(payload), jesc(mime))
    )


def row_text(needle):
    """innerText of the first tbody row containing `needle`."""
    try:
        return js(
            "(function(x){var r=Array.from(document.querySelectorAll('tbody tr')).find("
            "function(n){return (n.innerText||'').indexOf(x)>=0});"
            "return r?r.innerText.replace(/\\s+/g,' '):''})(%s)" % jesc(needle)
        ) or ""
    except Exception:
        return ""


def click_in_row(needle, label, scope=None):
    """Click `label` inside the first row that contains `needle` AND offers that
    control. Scanning every candidate row matters because a page can hold several
    tables (jobs, accounts, deletion flags) that all mention the same filename,
    and because an already-processed row no longer carries the button."""
    return js(
        "(function(x,l,sc){var rows=[];"
        "var roots=sc?Array.from(document.querySelectorAll('section')).filter("
        "function(s){var h=s.querySelector('h2');return h&&(h.innerText||'').indexOf(sc)>=0}):[document];"
        "roots.forEach(function(r){rows=rows.concat(Array.from(r.querySelectorAll('tbody tr')))});"
        "for(var i=0;i<rows.length;i++){if((rows[i].innerText||'').indexOf(x)<0)continue;"
        "var b=Array.from(rows[i].querySelectorAll('button,a')).find("
        "function(n){return ((n.innerText||'').trim().indexOf(l)>=0)&&!n.disabled});"
        "if(b){b.scrollIntoView({block:'center'});b.click();return true}}"
        "return false})(%s,%s,%s)"
        % (jesc(needle), jesc(label), jesc(scope) if scope else "null")
    )


