def rating_ready(timeout=30.0):
    """The panel disables every score button while a save transition is pending.

    Repeated runs start with a rating already stored, so waiting for the *text*
    to show the target value can return before the previous save settled. Wait
    for the buttons themselves to become enabled again instead.
    """
    end = time.time() + timeout
    while time.time() < end:
        if not count("button[aria-pressed][disabled]"):
            return True
        wait(0.5)
    return False


def click_rating(score):
    """Rating buttons are labelled 1..10, so an exact text match is required."""
    rating_ready()
    return js(
        "(function(x){var b=Array.from(document.querySelectorAll('button[aria-pressed]')).find("
        "function(n){return (n.innerText||'').trim()===x});"
        "if(!b||b.disabled)return false;b.scrollIntoView({block:'center'});b.click();return true})(%s)"
        % jesc(str(score))
    )


def own_rating(expected=None, timeout=30.0):
    """Poll until the panel reports the personal score (optionally a specific one)."""
    end = time.time() + timeout
    seen = ""
    while time.time() < end:
        seen = js(
            "(function(){var m=document.body.innerText.match(/Ihre Bewertung: \\d+ von 10/);"
            "return m?m[0]:''})()"
        ) or ""
        if seen and (expected is None or ("Ihre Bewertung: %d von 10" % expected) == seen):
            rating_ready()
            return seen
        wait(1.0)
    return seen


