    #    lists the same filenames but offers no delete control)
    for _ in range(8):
        go("/admin")
        wait(2.0)
        if not click_in_row(RUN, "Endg\u00fcltig l\u00f6schen", scope=FLAGGED_SECTION):
            break
        wait(1.5)
        setval('[role="dialog"] input', "L\u00d6SCHEN")
